create function public.create_workspace(workspace_name text) returns uuid language plpgsql security definer set search_path='' as $$
declare w uuid; u uuid := auth.uid();
begin
 if u is null then raise exception 'Authentication required'; end if;
 if length(btrim(workspace_name)) not between 1 and 100 then raise exception 'Invalid workspace name'; end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,0));
 select workspace_id into w from public.workspace_memberships where user_id=u and role='owner';
 if w is not null then return w; end if;
 insert into public.workspaces(name) values(btrim(workspace_name)) returning id into w;
 insert into public.workspace_memberships(workspace_id,user_id,role) values(w,u,'owner');
 return w;
end $$;

