create function public.protect_prospect() returns trigger language plpgsql set search_path='' as $$
begin
 if new.workspace_id<>old.workspace_id or new.created_by<>old.created_by or new.id<>old.id or new.created_at<>old.created_at or new.source_type<>old.source_type then raise exception 'Immutable prospect identity'; end if;
 if new.verification_status='user_verified' and old.verification_status<>'user_verified' then new.verified_at=now(); end if;
 if new.verification_status='unverified' then new.verified_at=null; end if;
 return new;
end $$;
