 if new.next_follow_up is distinct from old.next_follow_up then
 insert into public.prospect_activities(workspace_id,prospect_id,type,change_data,created_by) values(new.workspace_id,new.id,'follow_up_change',jsonb_build_object('from',old.next_follow_up,'to',new.next_follow_up),auth.uid()); end if;
