-- Definer required only for import batch writes; explicit membership and auth checks apply before any read/write.
create function public.import_prospects(w uuid, token uuid, filename text, rows jsonb, invalid_count integer) returns public.import_batches
language plpgsql security definer set search_path='' as $$
declare b public.import_batches; r jsonb; imported integer:=0; skipped integer:=0; result jsonb:='[]'; hash text; pid uuid; duplicate boolean;
begin
 if auth.uid() is null or not public.is_member(w) then raise exception 'Workspace access denied'; end if;
 if jsonb_typeof(rows)<>'array' or invalid_count<0 or jsonb_array_length(rows)+invalid_count>1000 then raise exception 'Invalid import size'; end if;
 hash := md5(rows::text || invalid_count::text || filename);
 perform pg_advisory_xact_lock(hashtextextended(w::text,1));
 select * into b from public.import_batches where workspace_id=w and idempotency_key=token;
 if found then
  if b.request_hash<>hash then raise exception 'Idempotency token reused with different data'; end if;
  return b;
 end if;
 for r in select value from jsonb_array_elements(rows) loop
  select exists(select 1 from public.prospects where workspace_id=w and public.duplicate_key(business_name,city,province,country)=public.duplicate_key(r->>'business_name',coalesce(r->>'city',''),coalesce(r->>'province',''),coalesce(r->>'country','Canada'))) into duplicate;
  if duplicate and not coalesce((r->>'allow_duplicate')::boolean,false) then
   skipped:=skipped+1; result:=result||jsonb_build_object('row',r->'row','status','skipped');
  else
   insert into public.prospects(workspace_id,business_name,industry,website_url,website_status,email,phone,city,province,country,source_type,source_reference,created_by)
   values(w,r->>'business_name',coalesce(r->>'industry',''),nullif(r->>'website_url',''),coalesce(nullif(r->>'website_status',''),'unknown')::public.website_status,nullif(r->>'email',''),nullif(r->>'phone',''),coalesce(r->>'city',''),coalesce(r->>'province',''),coalesce(r->>'country','Canada'),'csv_import',nullif(r->>'source_reference',''),auth.uid()) returning id into pid;
   imported:=imported+1; result:=result||jsonb_build_object('row',r->'row','status','imported','id',pid);
  end if;
 end loop;
 insert into public.import_batches(workspace_id,filename,status,total_count,imported_count,skipped_count,invalid_count,idempotency_key,request_hash,results,created_by)
 values(w,filename,'completed',jsonb_array_length(rows)+invalid_count,imported,skipped,invalid_count,token,hash,result,auth.uid()) returning * into b;
 return b;
end $$;
